import React, { useState } from 'react';
import { Mail, MapPin, Phone, Send } from 'lucide-react';
import { portfolioData } from '../../data/portfolioData';
import { useLanguage } from '../../context/LanguageContext';
import { PageWrapper } from '../../shared/components/PageWrapper';
import { portfolioManagerService } from '../../shared/services/portfolioManagerService';

const Contact = () => {
  const { language } = useLanguage();
  const t = portfolioData.common[language];
  const [formData, setFormData] = useState({ name: '', email: '', message: '' });
  const [sending, setSending] = useState(false);
  const [sent, setSent] = useState(false);
  const [sendError, setSendError] = useState('');
  const copy = {
    fr: {
      eyebrow: 'Contact',
      title: 'Recrutement ou collaboration ?',
      intro: 'Responsable RH ou recruteur, contactez-moi pour échanger sur une opportunité à distance ou sur mon parcours.',
      emailApp: 'Le formulaire prépare un courriel dans votre application de messagerie ; il ne transmet pas le message automatiquement.',
      subject: 'Candidature – Yousfi Mohammed',
      location: 'Localisation',
      emailLabel: 'Adresse e-mail',
      messageLabel: 'Votre message'
    },
    en: {
      eyebrow: 'Contact',
      title: 'Recruitment or collaboration?',
      intro: 'Recruiters and hiring managers are welcome to contact me about a remote opportunity or my background.',
      emailApp: 'The form prepares an email in your mail app; it does not send the message automatically.',
      subject: 'Application – Yousfi Mohammed',
      location: 'Location',
      emailLabel: 'Email address',
      messageLabel: 'Your message'
    },
    ar: {
      eyebrow: 'تواصل',
      title: 'توظيف أو تعاون؟',
      intro: 'يسعدني تواصل مسؤولي التوظيف لمناقشة فرصة عمل عن بُعد أو مساري الدراسي والمهني.',
      emailApp: 'يُعدّ النموذج رسالة في تطبيق البريد الإلكتروني ولا يرسلها تلقائياً.',
      subject: 'طلب توظيف – Yousfi Mohammed',
      location: 'الموقع',
      emailLabel: 'البريد الإلكتروني',
      messageLabel: 'رسالتك'
    },
    es: {
      eyebrow: 'Contacto',
      title: '¿Selección o colaboración?',
      intro: 'Responsables de selección y empresas pueden escribirme para hablar de una oportunidad remota o de mi trayectoria.',
      emailApp: 'El formulario prepara un correo en tu aplicación; no lo envía automáticamente.',
      subject: 'Candidatura – Yousfi Mohammed',
      location: 'Ubicación',
      emailLabel: 'Correo electrónico',
      messageLabel: 'Tu mensaje'
    }
  }[language];

  const handleSubmit = async (event) => {
    event.preventDefault();
    setSending(true);
    setSendError('');
    setSent(false);
    try {
      await portfolioManagerService.sendMessage({
        name: formData.name,
        email: formData.email,
        subject: copy.subject,
        message: formData.message
      });
      setSent(true);
      setFormData({ name: '', email: '', message: '' });
    } catch (error) {
      setSendError(error.message || 'Impossible d’envoyer le message.');
    } finally {
      setSending(false);
    }
  };

  const contactDetails = [
    { icon: Mail, label: t.email, value: 'myousfi610@gmail.com', href: 'mailto:myousfi610@gmail.com' },
    { icon: Phone, label: t.phone, value: '+212 716 288 974', href: 'tel:+212716288974' },
    { icon: MapPin, label: copy.location, value: t.locationValue }
  ];

  return (
    <PageWrapper>
      <header className="max-w-3xl">
        <p className="eyebrow">{copy.eyebrow}</p>
        <h1 className="display-heading mt-3 text-4xl leading-tight sm:text-5xl">{copy.title}</h1>
        <p className="mt-4 max-w-2xl text-base leading-7 text-[var(--muted)]">{copy.intro}</p>
      </header>

      <div className="mt-12 grid gap-10 md:grid-cols-[0.85fr_1.15fr] md:gap-16">
        <div className="space-y-3">
          {contactDetails.map((detail) => {
            const Icon = detail.icon;
            const content = (
              <>
                <span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-[var(--accent-soft)] text-[var(--accent)]">
                  <Icon size={18} />
                </span>
                <span className="min-w-0">
                  <span className="block text-xs text-[var(--muted)]">{detail.label}</span>
                  <span className="mt-0.5 block break-words text-sm font-medium">{detail.value}</span>
                </span>
              </>
            );
            return detail.href ? (
              <a key={detail.label} href={detail.href} className="surface-card flex items-center gap-4 p-4 transition-colors hover:border-[var(--accent)]">
                {content}
              </a>
            ) : (
              <div key={detail.label} className="surface-card flex items-center gap-4 p-4">
                {content}
              </div>
            );
          })}
          <a href="mailto:myousfi610@gmail.com" className="inline-flex items-center gap-2 px-1 pt-3 text-sm font-semibold text-[var(--accent)] hover:underline">
            <Mail size={16} />
            myousfi610@gmail.com
          </a>
        </div>

        <form onSubmit={handleSubmit} className="surface-card space-y-5 p-6 sm:p-8">
          <div>
            <label htmlFor="contact-name" className="mb-2 block text-sm font-medium">{t.name}</label>
            <input
              id="contact-name"
              type="text"
              required
              autoComplete="name"
              value={formData.name}
              onChange={(event) => setFormData({ ...formData, name: event.target.value })}
              className="w-full rounded-md border border-[var(--line)] bg-[var(--page)] px-4 py-3 text-sm text-[var(--ink)] placeholder:text-[var(--muted)] focus:border-[var(--accent)] focus:outline-none"
            />
          </div>
          <div>
            <label htmlFor="contact-email" className="mb-2 block text-sm font-medium">{t.email}</label>
            <input
              id="contact-email"
              type="email"
              required
              autoComplete="email"
              value={formData.email}
              onChange={(event) => setFormData({ ...formData, email: event.target.value })}
              className="w-full rounded-md border border-[var(--line)] bg-[var(--page)] px-4 py-3 text-sm text-[var(--ink)] focus:border-[var(--accent)] focus:outline-none"
            />
          </div>
          <div>
            <label htmlFor="contact-message" className="mb-2 block text-sm font-medium">{copy.messageLabel}</label>
            <textarea
              id="contact-message"
              rows="5"
              required
              value={formData.message}
              onChange={(event) => setFormData({ ...formData, message: event.target.value })}
              className="w-full resize-y rounded-md border border-[var(--line)] bg-[var(--page)] px-4 py-3 text-sm text-[var(--ink)] focus:border-[var(--accent)] focus:outline-none"
            />
          </div>
          <p className="text-xs leading-5 text-[var(--muted)]">{copy.emailApp}</p>
          {sent && <p role="status" className="text-sm text-emerald-400">Message envoyé avec succès.</p>}
          {sendError && <p role="alert" className="text-sm text-red-400">{sendError}</p>}
          <button type="submit" disabled={sending} className="inline-flex items-center gap-2 rounded-md bg-[var(--ink)] px-5 py-3 text-sm font-semibold text-[var(--page)] transition-colors hover:bg-[var(--accent)] disabled:opacity-50">
            <Send size={16} />
            {sending ? 'Envoi...' : t.send}
          </button>
        </form>
      </div>
    </PageWrapper>
  );
};

export default Contact;
