const API_URL = process.env.REACT_APP_PORTFOLIO_API_URL;

export const getPortfolioApiBaseUrl = () =>
  API_URL ? API_URL.replace(/\/$/, '') : null;

export const portfolioContentService = {
  async loadPublished() {
    const apiBaseUrl = getPortfolioApiBaseUrl();
    if (!apiBaseUrl) return null;

    try {
      const response = await fetch(`${apiBaseUrl}/api/v1/published`);
      if (!response.ok) return null;
      const data = await response.json();
      return data.documents || null;
    } catch (error) {
      console.warn('Published portfolio content is unavailable; using local fallback.', error);
      return null;
    }
  }
};
